package com.example.demo;import lombok.Getter;import java.util.List;@Getter public class MeetingResponse {private Long id;private String title;private String category;private String description;private String placeName;private Double latitude;private Double longitude;private String startsAt;private String createdAt;private int maxMembers;private Long currentMembers;private List<String> imageUrls;private String representativeImageUrl;private boolean confirmed;private String announcement;public MeetingResponse(Meeting meeting){this(meeting,null);}public MeetingResponse(Meeting meeting,Long currentMembers){this.id=meeting.getId();this.title=meeting.getTitle();this.category=meeting.getCategory();this.description=meeting.getDescription();this.placeName=meeting.getPlaceName();this.latitude=meeting.getLatitude();this.longitude=meeting.getLongitude();this.startsAt=meeting.getStartsAt();this.createdAt=meeting.getCreatedAt()==null?null:meeting.getCreatedAt().toString();this.maxMembers=meeting.getMaxMembers();this.currentMembers=currentMembers;this.imageUrls=meeting.getImageUrls()==null?List.of():List.copyOf(meeting.getImageUrls());this.representativeImageUrl=imageUrls.isEmpty()?null:imageUrls.get(0);this.confirmed=meeting.isConfirmed();this.announcement=meeting.getAnnouncement();}}